import { beforeEach, describe, expect, it, vi } from 'vitest';
import { act, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

// virtual:pwa-register is generated by vite-plugin-pwa; here it is replaced by a spy
interface RegisterOptions {
  onNeedRefresh?: () => void;
  onOfflineReady?: () => void;
}
const registerSW = vi.fn<(options?: RegisterOptions) => ((reload?: boolean) => Promise<void>) | undefined>();
vi.mock('virtual:pwa-register', () => ({ registerSW: (options?: RegisterOptions) => registerSW(options) }));

const { default: PwaUpdateNotice } = await import('../../components/PwaUpdateNotice');

const updateServiceWorker = vi.fn<(reload?: boolean) => Promise<void>>();
const lastOptions = (): RegisterOptions => registerSW.mock.calls.at(-1)![0]!;

beforeEach(() => {
  registerSW.mockReset();
  updateServiceWorker.mockReset();
  updateServiceWorker.mockResolvedValue(undefined);
  registerSW.mockReturnValue(updateServiceWorker);
});

describe('update notice', () => {
  it('registers the service worker once the app is on screen, and shows nothing yet', () => {
    render(<PwaUpdateNotice />);
    expect(registerSW).toHaveBeenCalledTimes(1);
    expect(screen.queryByRole('status')).not.toBeInTheDocument();
  });

  it('asks before switching when a new version has been downloaded', async () => {
    const user = userEvent.setup();
    render(<PwaUpdateNotice />);
    act(() => lastOptions().onNeedRefresh?.());

    const notice = await screen.findByRole('status');
    expect(notice).toHaveTextContent('Há uma versão nova do WorkEasy. Atualize para usá-la.');
    // Nothing reloads until the visitor says so
    expect(updateServiceWorker).not.toHaveBeenCalled();

    await user.click(screen.getByRole('button', { name: 'Atualizar' }));
    expect(updateServiceWorker).toHaveBeenCalledTimes(1);
    expect(updateServiceWorker).toHaveBeenCalledWith(true);
  });

  it('goes away on "Agora não" and does not come back for the same version', async () => {
    const user = userEvent.setup();
    render(<PwaUpdateNotice />);
    act(() => lastOptions().onNeedRefresh?.());
    await user.click(await screen.findByRole('button', { name: 'Agora não' }));
    expect(screen.queryByRole('status')).not.toBeInTheDocument();
    act(() => lastOptions().onNeedRefresh?.());
    expect(screen.queryByRole('status')).not.toBeInTheDocument();
    expect(updateServiceWorker).not.toHaveBeenCalled();
  });

  it('does not announce anything when the worker is only ready for offline use', () => {
    render(<PwaUpdateNotice />);
    act(() => lastOptions().onOfflineReady?.());
    expect(screen.queryByRole('status')).not.toBeInTheDocument();
  });

  it('does nothing, without failing, where there is no service worker (development, native apps)', async () => {
    registerSW.mockReturnValue(undefined);
    const user = userEvent.setup();
    render(<PwaUpdateNotice />);
    act(() => lastOptions().onNeedRefresh?.());
    await user.click(await screen.findByRole('button', { name: 'Atualizar' }));
    expect(updateServiceWorker).not.toHaveBeenCalled();
  });
});
